94	class AppManagerDomRuntime {
95	  private readonly _queryOne: <TElement extends Element>(selector: string) => TElement | null;
96	  private _aboutHeroSloganKeywordViewport: HTMLElement | null = null;
97	  private _aboutHeroSloganKeywordTrack: HTMLElement | null = null;
98	  private _aboutHeroSloganKeywordStep = 0;
99	  private _mainWhyShowcaseStage: HTMLElement | null = null;
100	  private _mainWhyShowcaseTitleLayers: HTMLElement[] = [];
101	  private _mainWhyShowcaseRing: HTMLElement | null = null;
102	  private _mainWhyShowcaseCards: HTMLElement[] = [];
103	  private _aboutUiPhase: AboutUiPhase = "idle";
104	
105	  constructor(
106	    queryOne: <TElement extends Element>(selector: string) => TElement | null,
107	  ) {
108	    this._queryOne = queryOne;
109	  }
110	
111	  setHeroHandoffVisible(visible: boolean): void {
112	    const heroSection = this._queryOne<HTMLElement>(HERO_SECTION_SELECTOR);
113	    if (!heroSection) return;
114	    heroSection.dataset.handoffVisible = visible ? "true" : "false";
115	  }
116	
117	  setAboutUiPhase(phase: AboutUiPhase): void {
118	    if (this._aboutUiPhase === phase) return;
119	    this._aboutUiPhase = phase;
120	    this._applyAboutUiVisibility();
121	  }
122	
123	  setAboutScenePlanesVisible(
124	    pageConfig: AboutPageConfig,
125	    visible: boolean,
126	  ): void {
127	    const elements = this._collectAboutScenePlaneElements(pageConfig);
128	    if (elements.length === 0) return;
129	    elements.forEach((element) => {
130	      element.style.opacity = visible ? "1" : "0";
131	      element.style.transform = visible
132	        ? "translate3d(0, 0, 0)"
133	        : "translate3d(0, 24px, 0)";
134	      element.style.pointerEvents = visible ? "" : "none";
135	      Aria.setHidden(element, !visible);
136	    });
137	  }
138	
139	  async revealAboutScenePlanes(
140	    pageConfig: AboutPageConfig,
141	    gsap: GsapGlobal | null,
142	  ): Promise<void> {
143	    const elements = this._collectAboutScenePlaneElements(pageConfig);
144	    if (elements.length === 0) return;
145	    if (!gsap) {
146	      this.setAboutScenePlanesVisible(pageConfig, true);
147	      return;
148	    }
149	    await new Promise<void>((resolve) => {
150	      elements.forEach((element) => {
151	        Aria.setHidden(element, false);
152	        element.style.pointerEvents = "";
153	      });
154	      gsap.to(elements, {
155	        opacity: 1,
156	        y: 0,
157	        duration: 0.72,
158	        stagger: 0.06,
159	        ease: "power3.out",
160	        onComplete: () => resolve(),
161	      });
162	    });
163	  }
164	
165	  waitForAboutHeroIntroClick(pageConfig: AboutPageConfig): Promise<void> {
166	    const triggerSelector = pageConfig.scrollSceneSelectors?.heroIntro;
167	    if (!triggerSelector) return Promise.resolve();
168	    const section = this._queryOne<HTMLElement>(triggerSelector);
169	    if (!section) return Promise.resolve();
170	    const trigger =
171	      section.querySelector<HTMLButtonElement>(ABOUT_HERO_INTRO_ACTION_SELECTOR);
172	    if (!trigger) return Promise.resolve();
173	    return new Promise<void>((resolve) => {
174	      const onClick = (): void => {
175	        trigger.removeEventListener("click", onClick);
176	        resolve();
177	      };
178	      trigger.addEventListener("click", onClick, { once: true });
179	    });
180	  }
181	
182	  scrollToAboutSceneProgress(
183	    pageConfig: AboutPageConfig,
184	    sceneKey: AboutSceneSectionKey,
185	    progress = 0,
186	  ): void {
187	    const selector = pageConfig.scrollSceneSelectors?.[sceneKey];
188	    if (!selector) return;
189	    const element = this._queryOne<HTMLElement>(selector);
190	    if (!element) return;
191	
192	    const rect = element.getBoundingClientRect();
193	    const top = window.scrollY + rect.top + rect.height * Helpers.clamp01(progress);
194	    window.scrollTo({ top, behavior: "auto" });
195	  }
196	
197	  disposeSceneIndicator(): void {
198	    this._aboutHeroSloganKeywordViewport = null;
199	    this._aboutHeroSloganKeywordTrack = null;
200	    this._aboutHeroSloganKeywordStep = 0;
201	    this._mainWhyShowcaseStage = null;
202	    this._mainWhyShowcaseTitleLayers = [];
203	    this._mainWhyShowcaseRing = null;
204	    this._mainWhyShowcaseCards = [];
205	  }
206	
207	  syncAboutUiScene(_sceneKey: AboutSceneSectionKey | null): void {
208	    this._applyAboutUiVisibility();
209	  }
210	
211	  syncAboutHeroSloganKeyword(
212	    sceneKey: AboutSceneSectionKey,
213	    progress: number,
214	    gsap: GsapGlobal | null,
215	  ): void {
216	    const viewport = this._resolveAboutHeroSloganKeywordViewport();
217	    const track = this._resolveAboutHeroSloganKeywordTrack();
218	    if (!viewport || !track) return;
219	
220	    if (!viewport.style.width) {
221	      this._initAboutHeroSloganKeywordViewportWidth(viewport, track);
222	    }
223	
224	    const nextStep = this._resolveAboutHeroSloganKeywordStep(sceneKey, progress);
225	    const shouldAnimate = sceneKey === "heroSlogan";
226	    if (
227	      this._aboutHeroSloganKeywordStep === nextStep &&
228	      shouldAnimate &&
229	      viewport.style.width.length > 0
230	    ) {
231	      return;
232	    }
233	
234	    this._aboutHeroSloganKeywordStep = nextStep;
235	    this._applyAboutHeroSloganKeywordStep(
236	      viewport,
237	      track,
238	      nextStep,
239	      shouldAnimate,
240	      gsap,
241	    );
242	  }
243	
244	  syncMainWhyShowcase(
245	    sceneKey: MainSceneSectionKey,
246	    progress: number,
247	  ): void {
248	    const stage = this._resolveMainWhyShowcaseStage();
249	    const titleLayers = this._resolveMainWhyShowcaseTitleLayers();
250	    const ring = this._resolveMainWhyShowcaseRing();
251	    const cards = this._resolveMainWhyShowcaseCards();
252	    if (!stage || !ring || cards.length === 0) return;
253	
254	    const showcaseProgress = this._resolveMainWhyShowcaseProgress(
255	      sceneKey,
256	      progress,
257	    );
258	    this._applyMainWhyShowcaseState(titleLayers, ring, cards, showcaseProgress);
259	  }
260	
261	  private _collectAboutScenePlaneElements(
262	    pageConfig: AboutPageConfig,
263	  ): HTMLElement[] {
264	    const selectorValues = Object.values(pageConfig.scrollSceneSelectors ?? {});
265	    const dedupedSelectors = Array.from(
266	      new Set(selectorValues.filter((selector): selector is string => !!selector)),
267	    );
268	    return dedupedSelectors
269	      .map((selector) => this._queryOne<HTMLElement>(selector))
270	      .filter((element): element is HTMLElement => element != null);
271	  }
272	
273	  private _resolveAboutHeroSloganKeywordTrack(): HTMLElement | null {
274	    if (this._aboutHeroSloganKeywordTrack?.isConnected) {
275	      return this._aboutHeroSloganKeywordTrack;
276	    }
277	    this._aboutHeroSloganKeywordTrack = this._queryOne<HTMLElement>(
278	      ABOUT_HERO_SLOGAN.trackSelector,
279	    );
280	    return this._aboutHeroSloganKeywordTrack;
281	  }
282	
283	  private _resolveMainWhyShowcaseProgress(
284	    sceneKey: MainSceneSectionKey,
285	    progress: number,
286	  ): number {
287	    if (sceneKey === "whyus") {
288	      return Helpers.clamp01(progress);
289	    }
290	
291	    const sceneOrder: readonly MainSceneSectionKey[] = [
292	      "intro",
293	      "hero",
294	      "story",
295	      "who",
296	      "whyus",
297	      "services",
298	      "works",
299	      "worksDetail",
300	      "worksFinal",
301	      "client",
302	      "contact",
303	    ];
304	    const currentIndex = sceneOrder.indexOf(sceneKey);
305	    const whyIndex = sceneOrder.indexOf("whyus");
306	    if (currentIndex > whyIndex) {
307	      return 1;
308	    }
309	    return 0;
310	  }
311	
312	  private _resolveAboutHeroSloganKeywordViewport(): HTMLElement | null {
313	    if (this._aboutHeroSloganKeywordViewport?.isConnected) {
314	      return this._aboutHeroSloganKeywordViewport;
315	    }
316	    this._aboutHeroSloganKeywordViewport = this._queryOne<HTMLElement>(
317	      ABOUT_HERO_SLOGAN.viewportSelector,
318	    );
319	    return this._aboutHeroSloganKeywordViewport;
320	  }
321	
322	  private _resolveAboutHeroSloganKeywordStep(
323	    sceneKey: AboutSceneSectionKey,
324	    progress: number,
325	  ): number {
326	    if (sceneKey !== "heroSlogan") return 0;
327	    const keywordCount = Math.max(ABOUT_HERO_SLOGAN.keywordCount, 1);
328	    const clampedProgress = Helpers.clamp01(progress);
329	    const windowedProgress = this._resolveAboutHeroSloganKeywordProgress(
330	      clampedProgress,
331	    );
332	    return Math.min(
333	      Math.floor(windowedProgress * keywordCount),
334	      keywordCount - 1,
335	    );
336	  }
337	
338	  private _resolveAboutHeroSloganKeywordProgress(progress: number): number {
339	    const start = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowStart);
340	    const end = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowEnd);
341	    if (end <= start) return progress;
342	    if (progress <= start) return 0;
343	    if (progress >= end) return 1;
344	    return (progress - start) / (end - start);
345	  }
