1041	  private _syncContactDomMotion(state: ContactDomState | null): void {
1042	    this._clearContactMotionTimers();
1043	    const blocks = this._resolveContactRevealBlocks();
1044	    const successBlocks = this._resolveContactSuccessBlocks();
1045	    const successTextNodes = this._resolveContactSuccessTextNodes();
1046	    if (state === CONTACT_THEATRE_DOM_STATE_READY) {
1047	      this._setContactBlocksDown(successBlocks);
1048	      TextReveal.setVisibleOff(successTextNodes);
1049	      this._staggerContactBlocks(blocks, true);
1050	      return;
1051	    }
1052	    if (state === CONTACT_THEATRE_DOM_STATE_LEAVING) {
1053	      this._staggerContactBlocks([...blocks].reverse(), false);
1054	      TextReveal.setVisibleOff(successTextNodes);
1055	      return;
1056	    }
1057	    if (state === CONTACT_THEATRE_DOM_STATE_SUCCESS) {
1058	      successBlocks.forEach((block) => {
1059	        block.classList.remove("is-block-reveal-down");
1060	        BlockReveal.reveal(block);
1061	      });
1062	      this._staggerContactText(successTextNodes, true);
1063	      return;
1064	    }
1065	    if (state === CONTACT_THEATRE_DOM_STATE_PENDING) {
1066	      this._hideContactBlocksImmediately(blocks);
1067	      this._hideContactBlocksImmediately(successBlocks);
1068	      TextReveal.setVisibleOff(successTextNodes);
1069	      return;
1070	    }
1071	    this._hideContactBlocksImmediately(blocks);
1072	    this._hideContactBlocksImmediately(successBlocks);
1073	    TextReveal.setVisibleOff(successTextNodes);
1074	  }
