69	function hasWorksTheatreSheetState(value: unknown): boolean {
70	  if (value == null || typeof value !== "object" || Array.isArray(value)) {
71	    return false;
72	  }
73	  const state = value as Record<string, unknown>;
74	  const sheetsById = state.sheetsById;
75	  if (sheetsById == null || typeof sheetsById !== "object" || Array.isArray(sheetsById)) {
76	    return false;
77	  }
78	  return Object.prototype.hasOwnProperty.call(sheetsById, "works");
79	}
