81	export function readWorksTheatreConfigSource(): WorksIntroTheatreConfig {
82	  const configState = worksIntroState as unknown as WorksIntroTheatreConfig;
83	  if (Array.isArray(configState.steps) && configState.steps.length > 0) {
84	    return {
85	      steps: configState.steps.map((step) => ({
86	        sheetId: "works",
87	        progressStart: step.progressStart,
88	        progressEnd: step.progressEnd,
89	        durationMs: Math.max(step.durationMs, WORKS_INTRO_DEFAULT_DURATION_MS),
90	      })),
91	    };
92	  }
93	  if (hasWorksTheatreSheetState(worksIntroState)) {
94	    return {
95	      steps: [
96	        {
97	          sheetId: "works",
98	          progressStart: 0,
99	          progressEnd: 1,
100	          durationMs: WORKS_INTRO_DEFAULT_DURATION_MS,
101	        },
102	      ],
103	    };
104	  }
105	  return { steps: [] };
106	}
